#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;
    std::cout << "Initial Capacity: " << v.capacity() << "\n";

    // Reserve memory to avoid multiple reallocations
    v.reserve(100); 
    std::cout << "Reserved Capacity: " << v.capacity() << "\n";

    // Push elements without causing reallocation
    for (int i = 0; i < 100; ++i) {
        v.push_back(i); 
    }
    // v.size() is 100, v.capacity() is >= 100

    // If we push 101st element, reallocation might occur (O(N) cost)
}
